'use client'

import { FormEvent, useRef, useState } from 'react'
import { ArrowRight, Bell, BookOpen, BookOpenCheck, Check, ChevronDown, CircleHelp, FileText, Headphones, Languages, LayoutDashboard, LogOut, Menu, Mic, MoreHorizontal, Plus, Search, Send, Settings, Sparkles, StopCircle, Users, Volume2 } from 'lucide-react'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Progress } from '@/components/ui/progress'
import ReferenceDashboard from '@/components/reference-dashboard'

type Role = 'teacher' | 'student'
type Language = 'Santhali' | 'Mundari' | 'Ho' | 'Kurukh'
type Lesson = { title: string; subject: string; className: string; icon: string; color: string; progress?: number; students?: number; updated?: string }
const languages: Language[] = ['Santhali', 'Mundari', 'Ho', 'Kurukh']
const studentLessons: Lesson[] = [{ title: 'The Water Cycle', subject: 'Science', className: 'Class 6', progress: 72, color: 'bg-[#dcece0]', icon: '💧' }, { title: 'Our Forest Friends', subject: 'Environmental Studies', className: 'Class 5', progress: 46, color: 'bg-[#f3e2c6]', icon: '🌿' }, { title: 'Fractions Around Us', subject: 'Mathematics', className: 'Class 6', progress: 90, color: 'bg-[#e8def0]', icon: '◒' }]
const teacherLessons: Lesson[] = [{ title: 'The Water Cycle', subject: 'Science', className: 'Class 6', students: 28, updated: 'Today, 9:42 AM', color: 'bg-[#dcece0]', icon: '💧' }, { title: 'Our Forest Friends', subject: 'Environmental Studies', className: 'Class 5', students: 24, updated: 'Yesterday', color: 'bg-[#f3e2c6]', icon: '🌿' }, { title: 'The Story of Birsa Munda', subject: 'Social Studies', className: 'Class 5', students: 24, updated: 'Aug 28, 2026', color: 'bg-[#f1ddd5]', icon: '◈' }]

function Brand({ light = false }: { light?: boolean }) { return <div className="flex items-center gap-3"><div className={`grid h-10 w-10 place-items-center rounded-xl ${light ? 'bg-[#d8a16c] text-[#315f4c]' : 'bg-primary text-primary-foreground'}`}><Languages size={21} /></div><div><p className={`font-display text-lg font-bold ${light ? '' : 'text-foreground'}`}>Vernacular</p><p className={`font-mono-ui text-[9px] uppercase tracking-[.18em] ${light ? 'text-white/60' : 'text-muted-foreground'}`}>Pedagogy platform</p></div></div> }

function AuthScreen({ onEnter }: { onEnter: (role: Role) => void }) {
  const [signup, setSignup] = useState(false); const [role, setRole] = useState<Role>('teacher'); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState('')
  function submit(event: FormEvent) { event.preventDefault(); if (!email.includes('@')) return setError('Enter a valid email address.'); if (password.length < 6) return setError('Password must be at least 6 characters.'); localStorage.setItem('vernacular-role', role); onEnter(role) }
  return <main className="grid min-h-screen lg:grid-cols-[1.08fr_.92fr]"><section className="relative hidden overflow-hidden bg-[#315f4c] p-12 text-[#f8f4e9] lg:flex lg:flex-col lg:justify-between"><div className="absolute -right-32 -top-32 h-[30rem] w-[30rem] rounded-full border border-white/10" /><div className="absolute -bottom-40 -left-36 h-[30rem] w-[30rem] rounded-full border border-white/10" /><Brand light /><div className="relative max-w-xl"><Badge variant="outline" className="mb-6 border-white/25 text-white/75">A classroom that speaks your language</Badge><h1 className="font-display text-6xl font-semibold leading-[.96] tracking-[-.05em]">Learning feels different when it feels like home.</h1><p className="mt-7 max-w-md text-sm leading-7 text-white/70">Bring every lesson closer to every learner with real-time translations across the languages of Jharkhand.</p><div className="mt-12 flex items-center gap-8 border-t border-white/15 pt-5 text-xs text-white/60"><span><strong className="block font-display text-2xl text-white">4</strong>languages</span><span><strong className="block font-display text-2xl text-white">1.2k</strong>active learners</span><span><strong className="block font-display text-2xl text-white">92%</strong>engagement</span></div></div><p className="relative font-mono-ui text-[10px] uppercase tracking-[.14em] text-white/45">Built for curious minds, everywhere.</p></section><section className="flex items-center justify-center bg-[#f7f3ea] px-6 py-12"><div className="w-full max-w-md"><div className="mb-10 lg:hidden"><Brand /></div><p className="font-mono-ui text-[10px] uppercase tracking-[.15em] text-muted-foreground">{signup ? 'Get started' : 'Welcome back'}</p><h2 className="mt-3 font-display text-4xl font-semibold tracking-[-.04em]">{signup ? 'Create your classroom.' : 'Your classroom awaits.'}</h2><p className="mt-3 text-sm leading-6 text-muted-foreground">{signup ? 'Start making lessons understandable for everyone.' : 'Sign in to continue your learning journey.'}</p><div className="my-7 grid grid-cols-2 rounded-lg bg-secondary p-1"><button onClick={() => { setSignup(false); setError('') }} className={`rounded-md py-2 text-sm font-semibold ${!signup ? 'bg-card shadow-sm' : 'text-muted-foreground'}`}>Log in</button><button onClick={() => { setSignup(true); setError('') }} className={`rounded-md py-2 text-sm font-semibold ${signup ? 'bg-card shadow-sm' : 'text-muted-foreground'}`}>Sign up</button></div><form onSubmit={submit} className="space-y-4"><label className="block text-xs font-semibold">Email address<input required value={email} onChange={event => setEmail(event.target.value)} className="mt-2 h-11 w-full rounded-md border bg-card px-3 text-sm outline-none focus:ring-2 focus:ring-ring" placeholder="you@example.com" type="email" /></label><label className="block text-xs font-semibold">Password<input required value={password} onChange={event => setPassword(event.target.value)} className="mt-2 h-11 w-full rounded-md border bg-card px-3 text-sm outline-none focus:ring-2 focus:ring-ring" placeholder="6 characters minimum" type="password" /></label>{signup && <div><p className="text-xs font-semibold">I am a...</p><div className="mt-2 grid grid-cols-2 gap-2">{(['teacher', 'student'] as Role[]).map(item => <button type="button" key={item} onClick={() => setRole(item)} className={`h-11 rounded-md border text-sm capitalize ${role === item ? 'border-primary bg-sage/15 text-primary' : 'bg-card text-muted-foreground'}`}>{item}</button>)}</div></div>}{error && <p role="alert" className="text-xs font-semibold text-coral">{error}</p>}<Button type="submit" className="h-11 w-full">{signup ? 'Create account' : 'Enter dashboard'}<ArrowRight size={16} /></Button></form><p className="mt-8 text-center text-xs text-muted-foreground">By continuing, you agree to our <span className="font-semibold text-primary">terms of learning</span>.</p></div></section></main>
}

function Sidebar({ role, active, navigate, logout }: { role: Role; active: string; navigate: (item: string) => void; logout: () => void }) { const links = [{ label: 'Overview', icon: LayoutDashboard }, { label: 'My Lessons', icon: role === 'teacher' ? FileText : BookOpenCheck }, { label: 'Translated Lessons', icon: Languages }, { label: 'Live Classroom', icon: Headphones }]; return <aside className="hidden w-[238px] shrink-0 border-r bg-[#fbf9f3] px-4 py-6 lg:flex lg:flex-col"><div className="mb-11 px-3"><Brand /></div><nav className="space-y-1">{links.map(({ label, icon: Icon }) => <button key={label} onClick={() => navigate(label)} className={`flex w-full items-center gap-3 rounded-md px-3 py-2.5 text-left text-xs font-semibold ${active === label ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:bg-secondary hover:text-foreground'}`}><Icon size={17} strokeWidth={1.8} />{label}</button>)}</nav><div className="mt-auto space-y-1 border-t pt-5"><button onClick={() => navigate('Settings')} className="flex w-full items-center gap-3 rounded-md px-3 py-2.5 text-xs font-semibold text-muted-foreground hover:bg-secondary"><Settings size={17} />Settings</button><button onClick={logout} className="flex w-full items-center gap-3 rounded-md px-3 py-2.5 text-xs font-semibold text-muted-foreground hover:bg-secondary"><LogOut size={17} />Sign out</button></div></aside> }

function LessonCard({ lesson, role, onOpen }: { lesson: Lesson; role: Role; onOpen: () => void }) { return <Card className="overflow-hidden border-0 bg-card shadow-soft transition-transform hover:-translate-y-1"><div className={`relative flex h-28 items-center justify-center ${lesson.color}`}><span className="text-5xl drop-shadow-sm">{lesson.icon}</span><button onClick={onOpen} aria-label={`Open ${lesson.title}`} className="absolute right-3 top-3 grid h-7 w-7 place-items-center rounded-full bg-white/60"><MoreHorizontal size={16} /></button></div><CardContent className="p-4"><div className="mb-3 flex items-start justify-between gap-3"><div><Badge variant="secondary" className="mb-2 text-[10px]">{lesson.className}</Badge><h3 className="font-display text-base font-bold">{lesson.title}</h3><p className="mt-1 text-xs text-muted-foreground">{lesson.subject}</p></div><span className="font-mono-ui text-[10px] text-muted-foreground">{role === 'student' ? `${lesson.progress}%` : `${lesson.students} students`}</span></div>{role === 'student' ? <Progress value={lesson.progress} className="h-1.5" /> : <div className="flex items-center justify-between border-t pt-3 text-[10px] text-muted-foreground"><span>Updated {lesson.updated}</span><ArrowRight size={14} className="text-primary" /></div>}</CardContent></Card> }

function LiveClassroom({ role, language, setLanguage }: { role: Role; language: Language; setLanguage: (value: Language) => void }) { const [live, setLive] = useState(false); const [transcript, setTranscript] = useState('“Press start to let your voice carry across the classroom...”'); const [translation, setTranslation] = useState('Translation will appear here for your students.'); const [speakerOn, setSpeakerOn] = useState(false); const recognition = useRef<any>(null); function toggle() { if (live) { recognition.current?.stop(); setLive(false); return }; const SpeechRecognition = typeof window !== 'undefined' && ((window as any).SpeechRecognition || (window as any).webkitSpeechRecognition); if (SpeechRecognition) { const instance = new SpeechRecognition(); instance.lang = 'hi-IN'; instance.continuous = true; instance.interimResults = true; instance.onresult = (event: any) => { const text = Array.from(event.results).map((result: any) => result[0].transcript).join(''); setTranscript(text); setTranslation(`[${language}] ${text}`) }; instance.start(); recognition.current = instance } else { setTranscript('नमस्ते विद्यार्थियों। आज हम पानी के बारे में सीखेंगे।'); setTranslation(`[${language}] Johar students. Today we learn about water.`) }; setLive(true) } function speak() { if (typeof window !== 'undefined' && translation && 'speechSynthesis' in window) { window.speechSynthesis.cancel(); window.speechSynthesis.speak(new SpeechSynthesisUtterance(translation)); setSpeakerOn(true); window.setTimeout(() => setSpeakerOn(false), 1800) } } return <div className="space-y-5"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="font-mono-ui text-[10px] uppercase tracking-[.15em] text-muted-foreground">Live classroom</p><h1 className="mt-2 font-display text-3xl font-semibold">Room 01 <Badge variant="coral" className="ml-2 align-middle text-[9px]">● On air</Badge></h1><p className="mt-2 text-sm text-muted-foreground">Teach in Hindi. Every student hears it in their language.</p></div><div className="flex items-center gap-2 text-xs text-sage"><Users size={15} /> 28 students connected</div></div><Card className="border-0 shadow-soft"><CardContent className="p-5 sm:p-7"><div className="flex flex-col gap-4 border-b pb-5 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-center gap-3"><div className={`grid h-12 w-12 place-items-center rounded-full ${live ? 'animate-pulse bg-coral/12 text-coral' : 'bg-secondary text-primary'}`}><Mic size={22} /></div><div><p className="font-mono-ui text-[9px] uppercase tracking-[.13em] text-muted-foreground">Teacher voice</p><p className="mt-1 text-sm font-bold">{live ? 'Listening in Hindi...' : 'Ready to broadcast'}</p></div></div><Button onClick={toggle} variant={live ? 'secondary' : 'default'}>{live ? <StopCircle size={16} /> : <Mic size={16} />}{live ? 'End live class' : 'Start live class'}</Button></div><div className="flex h-16 items-center gap-1.5 py-5">{Array.from({ length: 38 }).map((_, index) => <span key={index} className={`w-1 rounded-full ${live ? 'animate-pulse bg-coral' : 'bg-primary/25'}`} style={{ height: `${12 + ((index * 19) % 27)}px`, animationDelay: `${index * 28}ms` }} />)}</div><p className="font-mono-ui text-[9px] text-muted-foreground">Your Hindi speech appears here and translates in real time.</p></CardContent></Card><div className="grid gap-4 xl:grid-cols-2"><Card className="border-0 bg-[#f4efe5] shadow-none"><CardHeader className="pb-2"><CardTitle className="flex items-center gap-2 text-xs font-mono-ui uppercase tracking-[.09em] text-muted-foreground"><Headphones size={14} />Live transcript</CardTitle></CardHeader><CardContent><p className="min-h-20 font-serif text-base leading-7 text-foreground/75">{transcript}</p></CardContent></Card><Card className="border border-primary/10 bg-[#e7f0e8] shadow-none"><CardHeader className="pb-2"><div className="flex items-center justify-between"><CardTitle className="flex items-center gap-2 text-xs font-mono-ui uppercase tracking-[.09em] text-sage"><Languages size={14} />Student translation</CardTitle><select value={language} onChange={event => setLanguage(event.target.value as Language)} className="rounded border-0 bg-transparent text-[10px] font-semibold text-sage outline-none">{languages.map(item => <option key={item}>{item}</option>)}</select></div></CardHeader><CardContent><p className="min-h-20 font-serif text-base leading-7 text-sage">{translation}</p><div className="flex flex-wrap gap-3"><Button size="sm" variant="ghost" onClick={speak} className="px-0 text-sage hover:bg-transparent"><Volume2 size={14} />{speakerOn ? 'Playing translation' : 'Play aloud'}</Button><Button size="sm" variant="ghost" className="px-0 text-sage hover:bg-transparent"><Send size={14} />Send to screens</Button></div></CardContent></Card></div><p className="flex items-center gap-2 text-xs text-muted-foreground"><Sparkles size={14} className="text-[#c79360]" />{role === 'teacher' ? 'Your students see every translation instantly.' : 'Your teacher is broadcasting this lesson live.'}</p></div> }

function Stat({ label, value, note, primary = false }: { label: string; value: string; note: string; primary?: boolean }) { return <Card className={`border-0 shadow-soft ${primary ? 'bg-primary text-primary-foreground' : ''}`}><CardContent className="p-5"><div className="mb-7 flex items-center justify-between"><span className={`text-xs ${primary ? 'text-primary-foreground/70' : 'text-muted-foreground'}`}>{label}</span><Sparkles size={17} className={primary ? 'text-[#edc18f]' : 'text-coral'} /></div><p className="font-display text-3xl font-semibold">{value}</p><p className={`mt-2 text-[11px] ${primary ? 'text-primary-foreground/65' : 'text-muted-foreground'}`}>{note}</p></CardContent></Card> }

function Dashboard({ role, logout }: { role: Role; logout: () => void }) { const [active, setActive] = useState('Overview'); const [language, setLanguage] = useState<Language>('Santhali'); const [query, setQuery] = useState(''); const [classFilter, setClassFilter] = useState('All classes'); const [mobileMenu, setMobileMenu] = useState(false); const [notice, setNotice] = useState(''); const [notifications, setNotifications] = useState(false); const lessons = role === 'teacher' ? teacherLessons : studentLessons; const filtered = lessons.filter(lesson => `${lesson.title} ${lesson.subject}`.toLowerCase().includes(query.toLowerCase()) && (classFilter === 'All classes' || lesson.className === classFilter)); function announce(message: string) { setNotice(message); window.setTimeout(() => setNotice(''), 3000) } return <div className="flex min-h-screen bg-background"><Sidebar role={role} active={active} navigate={setActive} logout={logout} /><div className="min-w-0 flex-1"><header className="flex h-[76px] items-center justify-between border-b bg-[#fbf9f3]/80 px-5 sm:px-8"><button className="lg:hidden" onClick={() => setMobileMenu(!mobileMenu)} aria-label="Open navigation"><Menu size={21} /></button><div className="hidden items-center gap-2 text-xs text-muted-foreground sm:flex"><span className="text-foreground">Good morning, {role === 'teacher' ? 'Anita' : 'Aman'}.</span><span>•</span><span>Saturday, September 5, 2026</span></div><div className="relative flex items-center gap-3"><button onClick={() => setNotifications(!notifications)} aria-label="Notifications" className="relative text-muted-foreground"><Bell size={18} /><span className="absolute -right-1 -top-1 h-2 w-2 rounded-full bg-coral" /></button>{notifications && <div className="absolute right-10 top-10 z-30 w-64 rounded-lg border bg-card p-4 shadow-soft"><p className="font-display text-sm font-bold">Notifications</p><p className="mt-2 text-xs leading-5 text-muted-foreground">{role === 'teacher' ? 'Class 6 is ready for today’s lesson.' : 'Anita shared a new translated lesson.'}</p></div>}<div className="flex items-center gap-2 border-l pl-3"><div className="grid h-8 w-8 place-items-center rounded-full bg-[#d8e5d9] text-xs font-bold text-primary">{role === 'teacher' ? 'AS' : 'AR'}</div><div className="hidden sm:block"><p className="text-xs font-bold">{role === 'teacher' ? 'Anita Soren' : 'Aman Raj'}</p><p className="font-mono-ui text-[9px] capitalize text-muted-foreground">{role}</p></div><ChevronDown size={14} className="text-muted-foreground" /></div></div></header>{mobileMenu && <div className="absolute left-3 right-3 top-[68px] z-20 rounded-lg border bg-card p-3 shadow-soft lg:hidden"><div className="space-y-1">{['Overview', 'My Lessons', 'Translated Lessons', 'Live Classroom'].map(item => <button key={item} onClick={() => { setActive(item); setMobileMenu(false) }} className="block w-full rounded px-3 py-2 text-left text-sm hover:bg-secondary">{item}</button>)}</div></div>}<main className="mx-auto max-w-[1280px] px-5 py-8 sm:px-8 sm:py-10">{notice && <div role="status" className="fixed bottom-5 right-5 z-40 flex items-center gap-2 rounded-lg border bg-card px-4 py-3 text-xs font-semibold shadow-soft"><Check size={15} className="text-sage" />{notice}</div>}{active === 'Live Classroom' ? <LiveClassroom role={role} language={language} setLanguage={setLanguage} /> : <><section className="mb-8 flex flex-col justify-between gap-5 lg:flex-row lg:items-end"><div><div className="mb-3 flex items-center gap-2"><Badge variant="sage">{role === 'teacher' ? 'Teacher workspace' : 'Student workspace'}</Badge><span className="font-mono-ui text-[10px] text-muted-foreground">/ {active.toLowerCase()}</span></div><h1 className="font-display text-4xl font-semibold tracking-[-.05em] sm:text-5xl">{active === 'Overview' ? <>Make every lesson <em className="font-serif font-normal text-coral">understandable.</em></> : active}</h1><p className="mt-3 max-w-xl text-sm leading-6 text-muted-foreground">{role === 'teacher' ? 'Plan, translate, and share lessons with every learner in your classroom.' : 'Pick up where you left off and discover lessons made for you.'}</p></div><div className="flex gap-2">{role === 'teacher' && <Button size="sm" onClick={() => announce('New lesson workspace opened.')}><Plus size={15} />New lesson</Button>}<Button size="sm" variant="outline" onClick={() => announce('Help request noted.')}><CircleHelp size={15} />Help center</Button></div></section><section className="mb-8 grid gap-4 sm:grid-cols-3"><Stat primary label={role === 'teacher' ? 'Active learners' : 'Learning streak'} value={role === 'teacher' ? '76' : '12 days'} note={role === 'teacher' ? '+8 this week across 3 classes' : 'Keep going, Aman!'} /><Stat label={role === 'teacher' ? 'Lessons shared' : 'Lessons completed'} value={role === 'teacher' ? '18' : '7 / 12'} note={role === 'teacher' ? 'Across Classes 5 and 6' : '58% of your goal'} /><Stat label={role === 'teacher' ? 'Translations this month' : 'Your progress'} value={role === 'teacher' ? '124' : '68%'} note={role === 'teacher' ? 'Santhali is most popular' : '4 lessons ahead of last week'} /></section><div className="mb-5 flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><div><h2 className="font-display text-xl font-bold">{role === 'teacher' ? 'Your lesson library' : 'Continue learning'}</h2><p className="mt-1 text-xs text-muted-foreground">Recent lessons for Classes 5 and 6.</p></div><div className="flex gap-2"><label className="relative"><Search size={15} className="absolute left-3 top-2.5 text-muted-foreground" /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Search lessons" className="h-9 w-44 rounded-md border bg-card pl-9 pr-3 text-xs outline-none focus:ring-2 focus:ring-ring" /></label><select value={classFilter} onChange={event => setClassFilter(event.target.value)} aria-label="Filter by class" className="h-9 rounded-md border bg-card px-3 text-xs outline-none focus:ring-2 focus:ring-ring"><option>All classes</option><option>Class 5</option><option>Class 6</option></select></div></div><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{filtered.map(lesson => <LessonCard key={lesson.title} lesson={lesson} role={role} onOpen={() => announce(`${lesson.title} opened.`)} />)}</div>{filtered.length === 0 && <div className="rounded-lg border border-dashed p-10 text-center text-sm text-muted-foreground">No lessons match that search.</div>}<section className="mt-10 grid gap-5 lg:grid-cols-[1.15fr_.85fr]"><Card className="border-0 bg-[#f2e8d8] shadow-none"><CardContent className="flex min-h-40 flex-col justify-between p-6 sm:flex-row sm:items-end"><div><Badge variant="outline" className="border-[#c5a67d] bg-white/30">{role === 'teacher' ? 'Live classroom' : 'Next up'}</Badge><h2 className="mt-4 max-w-sm font-display text-2xl font-bold">{role === 'teacher' ? 'Ready to make today’s lesson travel further?' : 'The Water Cycle is waiting for you.'}</h2><p className="mt-2 text-xs text-foreground/60">{role === 'teacher' ? 'Connect with your class in Room 01.' : 'Science · Class 6 · 72% complete'}</p></div><Button onClick={() => setActive(role === 'teacher' ? 'Live Classroom' : 'My Lessons')} className="mt-5 w-fit bg-[#315f4c] hover:bg-[#244c3b]">{role === 'teacher' ? 'Open classroom' : 'Continue lesson'}<ArrowRight size={15} /></Button></CardContent></Card><Card className="border-0 shadow-soft"><CardHeader className="flex-row items-start justify-between pb-3"><div><CardTitle>Recent activity</CardTitle><CardDescription className="mt-1 text-xs">Classes 5 and 6</CardDescription></div><MoreHorizontal size={18} className="text-muted-foreground" /></CardHeader><CardContent className="space-y-3">{['Class 6 · The Water Cycle', 'Class 5 · Forest Friends', 'Class 6 · Fractions Around Us'].map((item, index) => <div key={item} className="flex items-center gap-3 border-t pt-3 first:border-0 first:pt-0"><div className="grid h-7 w-7 place-items-center rounded-md bg-secondary text-primary"><Check size={13} /></div><div className="min-w-0 flex-1"><p className="truncate text-xs font-semibold">{item}</p><p className="mt-1 text-[10px] text-muted-foreground">{index === 0 ? 'Today, 9:42 AM' : `${index + 1} days ago`}</p></div><ArrowRight size={13} className="text-muted-foreground" /></div>)}</CardContent></Card></section></>}</main></div></div> }

export default function Home() { const [role, setRole] = useState<Role | null>(null); function logout() { localStorage.removeItem('vernacular-role'); setRole(null) } return role ? <ReferenceDashboard role={role} onLogout={logout} /> : <AuthScreen onEnter={setRole} /> }
